'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto'),{gunzipSync}=require('node:zlib');
const root=__dirname,sha=b=>createHash('sha256').update(b).digest('hex');
test('every copied source byte or explicitly portable test edit matches its fixture seal',()=>{const seals=JSON.parse(fs.readFileSync(path.join(root,'fixture-seals.json'),'utf8')),edits=JSON.parse(fs.readFileSync(path.join(root,'portability-edits.json'),'utf8'));for(const row of seals.files){const bytes=fs.readFileSync(path.join(root,row.repository_path));assert.equal(sha(bytes),row.stored_sha256,row.repository_path);assert.equal(bytes.length,row.stored_bytes);const decoded=row.storage==='gzip-exact-original'?gunzipSync(bytes):bytes;assert.equal(sha(decoded),row.decoded_sha256);if(row.byte_exact)assert.equal(sha(decoded),row.source_sha256);else assert.ok(edits.edits.some(e=>e.path===row.repository_path&&e.before_sha256===row.source_sha256&&e.after_sha256===row.decoded_sha256));}});
test('final v2b runtime and replay profile/body anchors stay fixed without a full author rerun',()=>{assert.equal(sha(fs.readFileSync(path.join(root,'runtime.js'))),'e559bd68401cb16fb0a2ffaba60aeca11bf76dffc25d0880a9873e1223042dc9');assert.equal(sha(fs.readFileSync(path.join(root,'host/host-support.js'))),'9c890923f0a3a2efde15c18d38a7a3e2ebb8b015e79c051e239f0225aef05898');assert.equal(sha(fs.readFileSync(path.join(root,'native/adapter.js'))),'c64d0cbd78a767d56fa06b6f1e9fb37ce3a8f35289c5a13b1bc5a679fc41da4e');for(const name of ['abolish','train']){const dir=path.join(root,'replay',name),profile=gunzipSync(fs.readFileSync(path.join(dir,'profile.json.gz'))),html=gunzipSync(fs.readFileSync(path.join(dir,'body.html.gz'))),anchors=JSON.parse(fs.readFileSync(path.join(dir,'anchors.json'),'utf8'));assert.equal(sha(profile),anchors.profileSha256);assert.equal(sha(html),anchors.htmlSha256);}});
